challenge.solution:
const scans = [3, 7, -1, 12, 0, 5, 99, 4];
let total = 0;
let valid = 0;

// add up with a loop (use continue and break)
for (const value of scans) {
  if (value === 99) {
    break;
  }
  if (value < 0) {
    continue;
  }
  total += value;
  valid++;
}

console.log("Valid readings:", valid, "| Total:", total);

