project_task.solution:
const waves = [3, 5, 8];
let totalEnemies = 0;

// print and add up every wave with a loop
for (let i = 0; i < waves.length; i++) {
  console.log(`Wave ${i + 1}: ${waves[i]} enemies`);
  totalEnemies += waves[i];
}

// print the total
console.log(`Total: ${totalEnemies} enemies`);
